INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTX02PAQWE2XVTCGBDB78T8', 'bug', '06GCTR272F195FXFG583PV7FP8', 'Release workflow silently skipped every release after v2.8.1', 'release.yml only built when the v<version> git tag did not exist yet. Since T-393, make release creates and pushes that tag together with the release commit, so the workflow always found the tag and skipped build + publish — ''success'' with every job skipped. GitHub''s latest release stayed at v2.8.1 (2026-06-22), so the About-box update check compared against 2.8.1 and reported ''up to date'' on every newer build. Fix 2026-09-23: the version job checks for an existing GitHub Release instead of the tag; a workflow_dispatch ''tag'' input rebuilds an existing tag from its own tree (backfill); Windows removed from the release until the port is exercised (user decision). Verification: backfill v2.15.0, then cut 2.16.0 and confirm the check reports it.', 'backlog', 'high', NULL, NULL, NULL, '2026-09-23 08:48:47.282', '2026-09-23 08:48:47.282', NULL, '0589e9c209364f7a3c29e306b1852c20', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTX02PAQWE2XVTCGBDB78T8', 'bug', '06GCTR272F195FXFG583PV7FP8', 'Release workflow silently skipped every release after v2.8.1', 'release.yml only built when the v<version> git tag did not exist yet. Since T-393, make release creates and pushes that tag together with the release commit, so the workflow always found the tag and skipped build + publish — ''success'' with every job skipped. GitHub''s latest release stayed at v2.8.1 (2026-06-22), so the About-box update check compared against 2.8.1 and reported ''up to date'' on every newer build. Fix 2026-09-23: the version job checks for an existing GitHub Release instead of the tag; a workflow_dispatch ''tag'' input rebuilds an existing tag from its own tree (backfill); Windows removed from the release until the port is exercised (user decision). Verification: backfill v2.15.0, then cut 2.16.0 and confirm the check reports it.', 'review', 'high', NULL, NULL, NULL, '2026-09-23 08:48:47.282', '2026-09-23 08:48:56.036', NULL, 'b91de084e869e3b17a66d80d78152186', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR4K7V2NNTSGE89K0YAAXG', 'task', '06GCTR272F195FXFG583PV7FP8', 'Harden the GitHub workflows: pinned Flutter, tests gate releases, least privilege, SHA-pinned actions', 'Scan findings H7 (non-signing part), M9, M10, M11, L12, L17. release.yml publishes without depending on the test jobs and builds on the floating stable channel. Pin Flutter to .fvmrc in release.yml and test.yml; release requires the tests; publish SHA256SUMS (signing itself is T-491, minisign); pin every action by full SHA; add permissions: contents: read at the top of every workflow and scope write to the publish job; pin the pql download to a tag + checksum; pass windows-soak inputs through env: instead of inline expressions. Note T-491''s description (''workflows empty'') is stale — build on the existing release.yml.

Partial 2026-09-23 (with T-619): every workflow (test, release, windows, windows-soak) now installs the Flutter version pinned in .fvmrc instead of floating on stable. Floating had broken CI since at least v2.14.1: Flutter 3.47.5''s flutter_test pins test_api 0.7.12, incompatible with clide''s exact test 1.31.0 pin, so pub get failed in every job. Remaining here: tests gate releases, SHA256SUMS, SHA-pinned actions, least-privilege permissions, pql download pinning, windows-soak inputs via env.', 'backlog', 'high', NULL, NULL, NULL, '2026-09-23 08:27:33.566', '2026-09-23 08:53:59.279', NULL, '1df5ba62144bdaf1fc2a92ea77f7905e', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCV14SK05CKCT9SMX201JHHR', 'bug', '06GCTR272F195FXFG583PV7FP8', 'GitHub test workflow: three failures exposed once Flutter was pinned', 'Once CI installed the .fvmrc Flutter (T-608/T-619), pub get works again and the jobs get far enough to show three failures that the dependency error had hidden since at least v2.14.1. unit+coverage and bundle smoke pass. (1) dart doc: ~30 dartdoc warnings fail the --validate-links gate: unresolved doc references ([onChanged], [onEditStart]/[onEditEnd] in queued_messages_dock, [layoutSize], [D-43], bracketed prose like [Auto, when available], file-name refs like [tree_sitter_service_stub.dart]) plus an ambiguous re-export of shell_env via kernel/toolchain/toolchain_paths. Fix each ref (backticks for non-symbols) and settle the canonical export. Consider running dartdoc in make push-check so it can''t drift locally again. (2) web build (wasm compile gate): runs 
┌─ New feature ────────────────────────────────────────────────────────────────────────────┐
│   WebAssembly compilation is new. Understand the details before deploying to production. │
│   See https://flutter.dev/to/wasm for more information.                                  │
└──────────────────────────────────────────────────────────────────────────────────────────┘
Compiling lib/main.dart for the Web...                          
Expected to find fonts for (packages/cupertino_icons/CupertinoIcons, MaterialIcons), but found (). This usually means you are referring to font families in an IconData class but not including them in the assets section of your pubspec.yaml, are missing the package that would include them, or are missing "uses-material-design: true".
Compiling lib/main.dart for the Web...                             45.0s
✓ Built build/web directly, so lib/src/build_info.g.dart (gitignored, written by make gen-build-info) is missing. Run make gen-build-info first, or a make target. (3) integration_test companion_process_test ''turning the companion off leaves no claude process behind'' expects exactly one claude process, but CI has no claude binary, so it sees zero. Skip (with a reason) when claude isn''t on PATH, or give the test a fake claude. Acceptance: the test workflow is green on main.', 'backlog', 'high', NULL, NULL, NULL, '2026-09-23 09:06:54.488', '2026-09-23 09:06:54.488', NULL, 'b65a2d58c9386ad8d9db69513abc330b', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCV26X6YZG8T62EFW0J3J5XG', 'task', '06FB0TNQM7CEKQCMZAV751402G', 'Install updates from the About box: verified download, install swap, window relaunch (Linux)', 'T-47 P2+P3 for Linux, user request 2026-09-23 (''no button to install it … if the trayicon process is not updated, can we make it swap the windows for the new version''). Install button next to the update check + D-6 verb. Download the release''s linux tarball, verify against the SHA-256 digest GitHub records for the asset (interim, user decision 2026-09-23 — minisign verification replaces/extends it when T-491 lands), extract beside the install dir, swap by rename (old kept as .old), refresh the ~/.local/bin/clide client, then relaunch every open window on the new binary. The tray loader keeps running (protocol-compatible); it''s replaced naturally when the last old window exits. New windows wait for the old window''s socket to free before binding. Only offered for an installed bundle (not dev/build runs).', 'backlog', 'high', NULL, NULL, NULL, '2026-09-23 09:11:33.943', '2026-09-23 09:11:33.943', NULL, '3843c1e7e9f26efd862a26cf86bfeb05', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
