INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCV26X6YZG8T62EFW0J3J5XG', 'task', '06FB0TNQM7CEKQCMZAV751402G', 'Install updates from the About box: verified download, install swap, window relaunch (Linux)', 'T-47 P2+P3 for Linux, user request 2026-09-23 (''no button to install it … if the trayicon process is not updated, can we make it swap the windows for the new version''). Install button next to the update check + D-6 verb. Download the release''s linux tarball, verify against the SHA-256 digest GitHub records for the asset (interim, user decision 2026-09-23 — minisign verification replaces/extends it when T-491 lands), extract beside the install dir, swap by rename (old kept as .old), refresh the ~/.local/bin/clide client, then relaunch every open window on the new binary. The tray loader keeps running (protocol-compatible); it''s replaced naturally when the last old window exits. New windows wait for the old window''s socket to free before binding. Only offered for an installed bundle (not dev/build runs).

User test 2026-09-23 (2.16.0-labelled installer build → v2.17.0): the install and restart worked end to end. Follow-up fixed: the restarted window opened on the welcome page — the IPC side follows the cwd, but the UI''s startup only auto-opens a sticky recent (T-115). A relaunched window now reopens its working directory''s repo. The signal became a --relaunch argument, so terminals and Claude sessions don''t inherit it; CLIDE_RELAUNCH=1, which 2.17.0 sent, is still honoured.', 'review', 'high', NULL, NULL, NULL, '2026-09-23 09:11:33.943', '2026-09-23 09:37:01.630', NULL, '9c147eb8e881f3f05d6d081635e06106', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCV81K7V49V6HT370EBB4HP0', 'bug', '06FB0TNQM5TWC00GW0P3X02HZW', 'About box is too narrow: license lines clip on wide screens', 'User report 2026-09-23 (screenshot): the About box was fixed at 480 px, so the bundled-dependency lines (e.g. dugite-native''s license) were cut off with an ellipsis despite ample screen width. Fix: width follows the window (window − 80 px, between 480 and 760).', 'backlog', 'low', NULL, NULL, NULL, '2026-09-23 09:37:03.295', '2026-09-23 09:37:03.295', NULL, '09de3cd04ea5adada80080ea1fdd56f6', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCV81K7V49V6HT370EBB4HP0', 'bug', '06FB0TNQM5TWC00GW0P3X02HZW', 'About box is too narrow: license lines clip on wide screens', 'User report 2026-09-23 (screenshot): the About box was fixed at 480 px, so the bundled-dependency lines (e.g. dugite-native''s license) were cut off with an ellipsis despite ample screen width. Fix: width follows the window (window − 80 px, between 480 and 760).', 'review', 'low', NULL, NULL, NULL, '2026-09-23 09:37:03.295', '2026-09-23 09:37:05.218', NULL, '6b029340b5d57030b0b205384432a15c', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCSZV180Z4QKE0971S4MW8SC', 'story', NULL, 'Reopen last session''s secondary Claude tabs on demand', 'After an app reload the primary Claude pane continues its conversation (`--resume`, D-77), but secondary panes disappear. By design today: D-41 made secondaries ephemeral — each spawn gets a random id (`freshSessionId()`, claude_pane.dart) and the open secondary tabs are not persisted. The transcripts survive on disk (reachable via `/resume`), so nothing is lost; the tabs just don''t come back.

User report 2026-09-23: resume "works well … the main conversation seems to reliably continue after an app reload. Only thing is that conversations in secondary panels disappear."

Want: on relaunch, restore the workspace''s open secondary panes, each resuming its own session, in their previous order.

Shape: persist the ordered list of secondary session ids per workspace in user-scope state (D-93/D-53 — not in the repo); on boot, spawn a secondary per entry with `resume: true` when its transcript exists (skip entries whose transcript is gone). Closing a secondary removes it from the list. Forks (`--fork-session`) persist their resolved claude session id, not the fork source.

Needs a D-41 amendment: "secondaries are ephemeral" → "secondaries persist until closed".

Acceptance: open two secondaries, talk in each, restart clide → both tabs return with their conversations; a closed secondary does not come back; a secondary whose transcript was deleted is dropped silently.

Decision 2026-09-23 (user): NOT automatic restore. Reopen on demand instead — secondaries stay ephemeral across relaunch (D-41 unchanged), but clide remembers the workspace''s last set of open secondary session ids (user-scope state, not the repo) and offers a ''Reopen last session''s tabs'' command (+ D-6 CLI verb), which re-spawns each with resume where the transcript still exists, in the previous order. Acceptance changes accordingly: after restart the tabs are NOT back; invoking the command brings them back with their conversations; a deleted transcript is skipped silently.', 'in_progress', 'medium', NULL, NULL, 'D-41', '2026-09-23 06:41:23.776', '2026-09-23 09:44:20.082', NULL, '432548da1fa50b7f090bcf651def0052', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
