INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVC26FASPNAK7NFK54T1P7M', 'task', '06FB0TNQM5TWC00GW0P3X02HZW', 'D-6 gap: extension palette commands have no CLI verb', 'Found 2026-09-23 while adding claude.restore: CommandContribution commands registered by extensions (e.g. claude.new-secondary, claude.kill-all-sessions, and most palette entries) are reachable from the palette and keybindings only — CommandRegistry never reaches the IPC dispatcher, so ''clide claude new-secondary'' is an unknown command. D-6 promises every UI action a CLI verb. Options: route a generic verb (e.g. ''clide command run <id>'') through CommandRegistry, or have ExtensionsManager register each CommandContribution.command as a dispatcher verb (with the run callback''s IpcResponse, which the contribution already returns). The second keeps ''clide <subsystem> <verb>'' naming and makes capabilities list them. claude.restore was added directly for now.', 'backlog', 'medium', NULL, NULL, NULL, '2026-09-23 09:54:36.794', '2026-09-23 09:54:36.794', NULL, 'e697595b9d434470b386b399839c4509', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
