INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCV14SK05CKCT9SMX201JHHR', 'bug', '06GCTR272F195FXFG583PV7FP8', 'GitHub test workflow: three failures exposed once Flutter was pinned', 'Once CI installed the .fvmrc Flutter (T-608/T-619), pub get works again and the jobs get far enough to show three failures that the dependency error had hidden since at least v2.14.1. unit+coverage and bundle smoke pass. (1) dart doc: ~30 dartdoc warnings fail the --validate-links gate: unresolved doc references ([onChanged], [onEditStart]/[onEditEnd] in queued_messages_dock, [layoutSize], [D-43], bracketed prose like [Auto, when available], file-name refs like [tree_sitter_service_stub.dart]) plus an ambiguous re-export of shell_env via kernel/toolchain/toolchain_paths. Fix each ref (backticks for non-symbols) and settle the canonical export. Consider running dartdoc in make push-check so it can''t drift locally again. (2) web build (wasm compile gate): runs 
┌─ New feature ────────────────────────────────────────────────────────────────────────────┐
│   WebAssembly compilation is new. Understand the details before deploying to production. │
│   See https://flutter.dev/to/wasm for more information.                                  │
└──────────────────────────────────────────────────────────────────────────────────────────┘
Compiling lib/main.dart for the Web...                          
Expected to find fonts for (packages/cupertino_icons/CupertinoIcons, MaterialIcons), but found (). This usually means you are referring to font families in an IconData class but not including them in the assets section of your pubspec.yaml, are missing the package that would include them, or are missing "uses-material-design: true".
Compiling lib/main.dart for the Web...                             45.0s
✓ Built build/web directly, so lib/src/build_info.g.dart (gitignored, written by make gen-build-info) is missing. Run make gen-build-info first, or a make target. (3) integration_test companion_process_test ''turning the companion off leaves no claude process behind'' expects exactly one claude process, but CI has no claude binary, so it sees zero. Skip (with a reason) when claude isn''t on PATH, or give the test a fake claude. Acceptance: the test workflow is green on main.', 'in_progress', 'high', NULL, NULL, NULL, '2026-09-23 09:06:54.488', '2026-09-23 10:24:54.083', NULL, '58afc876834f0cbe64bf9bbcbb5368ac', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCV14SK05CKCT9SMX201JHHR', 'bug', '06GCTR272F195FXFG583PV7FP8', 'GitHub test workflow: three failures exposed once Flutter was pinned', 'Once CI installed the .fvmrc Flutter (T-608/T-619), pub get works again and the jobs get far enough to show three failures that the dependency error had hidden since at least v2.14.1. unit+coverage and bundle smoke pass.

(1) dart doc: ~35 dartdoc warnings fail the --validate-links gate: unresolved doc references ([onChanged], [onEditStart]/[onEditEnd] in queued_messages_dock, [layoutSize], [D-43], bracketed prose like [Auto, when available], file-name refs like [tree_sitter_service_stub.dart]) plus an ambiguous re-export of shell_env via kernel/toolchain/toolchain_paths. Fix each ref (backticks for non-symbols) and settle the canonical export. Consider running dartdoc in make push-check so it can''t drift locally again.

(2) web build (wasm compile gate): the job runs ''flutter build web --wasm'' directly, so lib/src/build_info.g.dart (gitignored, written by make gen-build-info) is missing. Run make gen-build-info first.

(3) integration_test companion_process_test ''turning the companion off leaves no claude process behind'' expects exactly one claude process, but CI has no claude binary, so it sees zero. Skip (with a reason) when claude isn''t on PATH, or give the test a fake claude.

Acceptance: the test workflow is green on main.

Note 2026-09-23: this description was first filed through a shell command whose backticks were executed (command substitution), which pasted flutter build output into it; rewritten from a file.', 'in_progress', 'high', NULL, NULL, NULL, '2026-09-23 09:06:54.488', '2026-09-23 10:25:42.404', NULL, 'dd8da44c898f60f4403a146bc659cce6', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR572MH8PSQ8CZXQGCKEKR', 'bug', '06GCTR272F195FXFG583PV7FP8', 'Editor save must use the write-path resolver', 'Scan finding M2 (verified 2026-09-23). EditorRegistry resolves save targets with resolveUnderRootFollowingSymlinks — the read resolver — at lib/src/editor/registry.dart:267. For a not-yet-existing file under a symlinked directory it can resolve outside the workspace. resolveForWriteUnderRoot exists for exactly this; use it in save(). Test: a save through a symlinked-out directory is rejected, as files.write already does (T-102).', 'in_progress', 'medium', NULL, NULL, NULL, '2026-09-23 08:27:38.645', '2026-09-23 10:32:33.465', NULL, '065d1a26906db1df67e451d22fd8ad3e', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR572MH8PSQ8CZXQGCKEKR', 'bug', '06GCTR272F195FXFG583PV7FP8', 'Editor save must use the write-path resolver', 'Scan finding M2 (verified 2026-09-23). EditorRegistry resolves save targets with resolveUnderRootFollowingSymlinks — the read resolver — at lib/src/editor/registry.dart:267. For a not-yet-existing file under a symlinked directory it can resolve outside the workspace. resolveForWriteUnderRoot exists for exactly this; use it in save(). Test: a save through a symlinked-out directory is rejected, as files.write already does (T-102).', 'review', 'medium', NULL, NULL, NULL, '2026-09-23 08:27:38.645', '2026-09-23 10:33:03.448', NULL, 'eacbb4e4ff21b4e3caa95af2a727f136', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR360YN0X13FHBNGYWN05C', 'bug', '06GCTR272F195FXFG583PV7FP8', 'Agent clide-CLI lookup must not use the workspace''s native/ directory', 'Scan finding H2. agent_bootstrap.dart builds the clide-CLI candidate list with $workspaceRoot/native/<abi> and then prepends the whole chosen directory to the hosted session''s PATH. Drop the workspace candidate (or gate it behind an explicit dev opt-in for the clide source tree only), and expose just the single clide binary (e.g. a symlink in a private per-session dir) rather than a whole directory. Spawn claude from its resolved absolute path (D-104). Same class as T-98 (dugite from the workspace). Test: a workspace native/ dir containing executables never reaches the agent PATH.', 'in_progress', 'high', NULL, NULL, NULL, '2026-09-23 08:27:21.991', '2026-09-23 10:33:11.087', NULL, '7dca56ab976c2335a14f3110cc88df70', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR360YN0X13FHBNGYWN05C', 'bug', '06GCTR272F195FXFG583PV7FP8', 'Agent clide-CLI lookup must not use the workspace''s native/ directory', 'Scan finding H2. agent_bootstrap.dart builds the clide-CLI candidate list with $workspaceRoot/native/<abi> and then prepends the whole chosen directory to the hosted session''s PATH. Drop the workspace candidate (or gate it behind an explicit dev opt-in for the clide source tree only), and expose just the single clide binary (e.g. a symlink in a private per-session dir) rather than a whole directory. Spawn claude from its resolved absolute path (D-104). Same class as T-98 (dugite from the workspace). Test: a workspace native/ dir containing executables never reaches the agent PATH.

Done 2026-09-23: the CLI candidates are ~/.local/bin/clide, the bundle''s clide-cli, and (only when the app runs from a clide source tree''s build/ dir) that tree''s native/<abi>/clide — never the opened workspace. Whatever is chosen is exposed as a single ''clide'' symlink in <socket dir>/bin (0700, D-71), so no other executable reaches the agent''s PATH. Also fixed on the way: the old last candidate was the bundle dir, whose ''clide'' is the GUI binary, so a CLI-less install pointed agents at a new window. Not done here: spawning claude by resolved absolute path (D-104) — with only the single-link dir prepended, the workspace can no longer shadow claude via this path; the remaining vector is the user''s own app-scope PATH preset (D-106), which is user-controlled.', 'in_progress', 'high', NULL, NULL, NULL, '2026-09-23 08:27:21.991', '2026-09-23 10:34:26.060', NULL, '91e89622d197d11a91db7765c80cb08f', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
