INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS716CQQS0TCFR1NYBFBPG', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Terminal: DECCKM (CSI ?1h) is ignored for arrow keys', 'Audit #6 (verified). core/input/handler.dart:117 picks arrow-key encoding from appKeypadMode instead of cursorKeysMode, so application cursor mode (ESC O A) never applies; vim/less rely on it. Masked: the input test fake hard-codes cursorKeysMode false and the mode test only checks the getter. Fix plus a test through the real terminal state.', 'in_progress', 'high', NULL, NULL, NULL, '2026-09-23 10:52:04.275', '2026-09-23 10:53:52.732', NULL, '62a2595895c256d7f470f376cc0159bc', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS716CQQS0TCFR1NYBFBPG', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Terminal: DECCKM (CSI ?1h) is ignored for arrow keys', 'Audit #6 (verified). core/input/handler.dart:117 picks arrow-key encoding from appKeypadMode instead of cursorKeysMode, so application cursor mode (ESC O A) never applies; vim/less rely on it. Masked: the input test fake hard-codes cursorKeysMode false and the mode test only checks the getter. Fix plus a test through the real terminal state.', 'review', 'high', NULL, NULL, NULL, '2026-09-23 10:52:04.275', '2026-09-23 10:54:24.728', NULL, 'bd1d4771914595ddb6da410ca8005a51', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS6188ZN35KEPY6S8EWC2W', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Terminal: HTS (ESC H) never sets a tab stop', 'Audit #1 (verified). terminal.dart:455 calls isSetAt (a read) instead of setAt, so ESC H is a no-op. Locked in by terminal_test.dart:393 (''setTapStop is a query, not a write''). Fix the handler and the test: after ESC H at column N, a TAB from before N stops at N.', 'in_progress', 'medium', NULL, NULL, NULL, '2026-09-23 10:51:56.098', '2026-09-23 10:54:32.160', NULL, '31ac02ce1455bce07965c1473e198a8f', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
