INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS6TDDJAHYJZVPHYPP931G', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Terminal: DECAWM off (CSI ?7l) still wraps to the next line', 'Audit #5 (verified). With autowrap off, printing past the right margin must overwrite the last column; core/buffer/buffer.dart:110-116 still wraps. Masked by buffer_test.dart:212, which only checks isWrapped. Test: with ?7l, writing ''abc'' on a 2-column line leaves ''ac'' and the cursor on the same row.', 'in_progress', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:02.539', '2026-09-23 10:55:31.077', NULL, '4f9ba80262305f17b5223f516f90cfb3', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
