INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS773CTD84YD95SBYBD9W8', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Scheduler leaks subscriptions and timers after close/dispose', 'Audit #7 (verified). lib/kernel/src/scheduler.dart:52,64: the ProjectClosed subscription is never stored or cancelled, so listeners pile up on every start(); the four staggered initial Timers are never cancelled, so ticks fire after close. Masked by services_bigger_test.dart:212, which asserts nothing.', 'in_progress', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:05.787', '2026-09-23 10:56:06.707', NULL, '521d40adc801f5c2cb6024e3977b96c2', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
