INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS7KTWH1BYEGJK6GYV8AGG', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'IPC envelope: wrong-type fields become internal toolErrors', 'Audit #10 (verified). envelope.dart:40: j[''id'']! as String throws a TypeError (not a FormatException), so a request like {id: 1} is reported as an internal toolError with id ''''. The v (schema version) field is never checked. Should be a userError naming the bad field; unknown/mismatched v should be rejected clearly.', 'in_progress', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:09.047', '2026-09-23 10:56:56.354', NULL, 'b62f87d8d584a890f86cc7e0bc001891', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
