INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS7TCSD4K8NS65TTFB9564', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'git apply: launch failure escapes unwrapped; stderr read can deadlock', 'Audit #11 (verified). git/client.dart:230-237 _applyPatch calls Process.start without the ProcessException wrapping _run has, and reads stderr only after exitCode, so a large stderr can deadlock the pipe. Worked around in git_commands_errors_test.dart:48-52, which excludes the hunk commands. Wrap like _run and read stdout/stderr concurrently.', 'in_progress', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:10.726', '2026-09-23 10:57:54.254', NULL, '2a15eefaf0c06b294e99c48b4c4f7876', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS7TCSD4K8NS65TTFB9564', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'git apply: launch failure escapes unwrapped; stderr read can deadlock', 'Audit #11 (verified). git/client.dart:230-237 _applyPatch calls Process.start without the ProcessException wrapping _run has, and reads stderr only after exitCode, so a large stderr can deadlock the pipe. Worked around in git_commands_errors_test.dart:48-52, which excludes the hunk commands. Wrap like _run and read stdout/stderr concurrently.', 'review', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:10.726', '2026-09-23 10:59:09.534', NULL, '7cd47d6b13414c476961ae16229842a6', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS7CWH6V9W6B5CWCV9WMC0', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Decision reader shows stale data when replies arrive out of order', 'Audit #9 (verified). decision_detail_view.dart:54-66: _load has no request token, so a slow reply for D-1 arriving after D-5 overwrites D-5. Masked: decision_reader_test.dart:268 uses a synchronous stub. Needs a deferred (Completer-backed) stub to test the race.', 'in_progress', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:07.268', '2026-09-23 10:59:18.585', NULL, 'b68fcb695527a106bb9c4526a83370e9', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS7CWH6V9W6B5CWCV9WMC0', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Decision reader shows stale data when replies arrive out of order', 'Audit #9 (verified). decision_detail_view.dart:54-66: _load has no request token, so a slow reply for D-1 arriving after D-5 overwrites D-5. Masked: decision_reader_test.dart:268 uses a synchronous stub. Needs a deferred (Completer-backed) stub to test the race.', 'review', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:07.268', '2026-09-23 10:59:58.936', NULL, '0862fde3dadeaa3f27b2dd364dcdc92a', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS87HRPVQ7W4MENAAK6GD4', 'task', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Verify and fix the reviewer-reported bugs #12-19 from the test audit', 'Audit section 1, rows 12-19, reported by reviewers but not re-verified: IRM and focus reporting stored but unused (12); keymap when-false binding falls through to a lower layer, _rebuildActive uses notifyListeners (13); CommandRegistry.register silently overwrites an id and the first owner''s unregister removes the second''s (14); terminal parser gaps, DCS/SOS/PM/APC printed as text, ESC/CAN/SUB don''t abort CSI, huge CSI param spins (15, overlaps T-612); pql retry matches any stderr containing ''locked'' and has no timeout (16); _reap uses WNOHANG so a late-exiting child can be left a zombie (17); team-chat rows keyed by microsecondsSinceEpoch collide (18); editor echo suppression is a single boolean (19). Confirm each in the source, then fix with a failing test first, or split out.', 'review', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:14.094', '2026-09-23 11:16:11.031', NULL, '3b7cb367f253e5e4b08358c508bd639d', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR5QEKXZ0VTVWRWKS1M28G', 'bug', '06GCTR272F195FXFG583PV7FP8', 'Terminal parser: bound CSI parameters, REP, window ops and OSC length', 'Scan finding M4. Untrusted terminal output (cat of a file, git log on a repo) can freeze or exhaust the app: CSI parameters accumulate unclamped, REP repeats unbounded, the window-size op resizes to any size, and the OSC buffer is unbounded. Clamp parameters to 65535, cap REP at cols×rows, ignore window-manipulation ops (xterm''s default), cap OSC length. Code: lib/src/terminal/src/core/escape/{parser,csi_handlers,osc_handlers}.dart, terminal.dart.', 'review', 'medium', NULL, NULL, NULL, '2026-09-23 08:27:42.836', '2026-09-23 11:16:11.038', NULL, '7c1bd5abbabbaa8c004a5d9f1d6cc6b6', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS87HRPVQ7W4MENAAK6GD4', 'task', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Verify and fix the reviewer-reported bugs #12-19 from the test audit', 'Audit section 1, rows 12-19, reported by reviewers but not re-verified: IRM and focus reporting stored but unused (12); keymap when-false binding falls through to a lower layer, _rebuildActive uses notifyListeners (13); CommandRegistry.register silently overwrites an id and the first owner''s unregister removes the second''s (14); terminal parser gaps, DCS/SOS/PM/APC printed as text, ESC/CAN/SUB don''t abort CSI, huge CSI param spins (15, overlaps T-612); pql retry matches any stderr containing ''locked'' and has no timeout (16); _reap uses WNOHANG so a late-exiting child can be left a zombie (17); team-chat rows keyed by microsecondsSinceEpoch collide (18); editor echo suppression is a single boolean (19). Confirm each in the source, then fix with a failing test first, or split out.', 'done', 'medium', NULL, NULL, NULL, '2026-09-23 10:52:14.094', '2026-09-23 11:19:13.223', NULL, 'd3789bae4194f0283882e2daa6398974', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR5QEKXZ0VTVWRWKS1M28G', 'bug', '06GCTR272F195FXFG583PV7FP8', 'Terminal parser: bound CSI parameters, REP, window ops and OSC length', 'Scan finding M4. Untrusted terminal output (cat of a file, git log on a repo) can freeze or exhaust the app: CSI parameters accumulate unclamped, REP repeats unbounded, the window-size op resizes to any size, and the OSC buffer is unbounded. Clamp parameters to 65535, cap REP at cols×rows, ignore window-manipulation ops (xterm''s default), cap OSC length. Code: lib/src/terminal/src/core/escape/{parser,csi_handlers,osc_handlers}.dart, terminal.dart.', 'done', 'medium', NULL, NULL, NULL, '2026-09-23 08:27:42.836', '2026-09-23 11:19:17.717', NULL, '42ccf5cbc607c87ca347709464aa2063', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS96Q7RVQTEXK8R1AB7E4M', 'task', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Keep tests off the host: pql fixture vault, socketDir override, git sandbox', 'Audit 2.4 / plan item 3. pql tests read and write the live planning DB (client_test, pql_commands_test calling decisions.sync) — use a fixture vault in a temp dir or the argv-echo fake-pql (client_test.dart:170), which also lets the serial tag go. IPC tests use the real XDG_RUNTIME_DIR/clide (withXdg does nothing) and can probe/unlink a running clide''s sockets — give IpcServer and the path helpers a socketDir override like McpServer.discoveryDirOverride. Git sandboxes inherit global git config: add test/helpers/git_sandbox.dart with GIT_CONFIG_GLOBAL=/dev/null and GIT_CONFIG_NOSYSTEM=1, check git exit codes. Stop reading the real checkout (file_actions_test:27), ~/.clide/extensions (host_test:62) and host CLIDE_DUGITE_DIR (toolchain_test:105).', 'in_progress', 'high', NULL, NULL, NULL, '2026-09-23 10:52:22.073', '2026-09-23 11:42:10.192', NULL, '3589d60c26e378cfb0e8827c1ee0fe10', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCVS96Q7RVQTEXK8R1AB7E4M', 'task', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'Keep tests off the host: pql fixture vault, socketDir override, git sandbox', 'Audit 2.4 / plan item 3. pql tests read and write the live planning DB (client_test, pql_commands_test calling decisions.sync) — use a fixture vault in a temp dir or the argv-echo fake-pql (client_test.dart:170), which also lets the serial tag go. IPC tests use the real XDG_RUNTIME_DIR/clide (withXdg does nothing) and can probe/unlink a running clide''s sockets — give IpcServer and the path helpers a socketDir override like McpServer.discoveryDirOverride. Git sandboxes inherit global git config: add test/helpers/git_sandbox.dart with GIT_CONFIG_GLOBAL=/dev/null and GIT_CONFIG_NOSYSTEM=1, check git exit codes. Stop reading the real checkout (file_actions_test:27), ~/.clide/extensions (host_test:62) and host CLIDE_DUGITE_DIR (toolchain_test:105).', 'review', 'high', NULL, NULL, NULL, '2026-09-23 10:52:22.073', '2026-09-23 11:53:08.431', NULL, 'b0ad32619beffc3ec8cf8ec2b346ed8c', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR2W244VDCCYYYMZE823MR', 'story', '06GCTR272F195FXFG583PV7FP8', 'Risk tiers for clide verbs: generated agent allow rules + in-app confirm for escalating verbs', 'Scan finding H1 (+ the report''s allowlist proposal). Hosted Claude sessions are pre-approved for every clide verb, including verbs that spawn processes or write to panes. Plan: (1) a required risk tier on every registry command — observe / display / workspace-write / escalate — enforced by a registry test so no verb ships unclassified; (2) generate the agent''s Claude allow rules from the observe+display tiers (a capabilities flag), replacing the blanket rule in agent_bootstrap and the committed .claude/settings.json; (3) the dispatcher asks the user in-app before any escalate verb arriving over the socket, showing full argv/env/target; (4) an app-scope allowlist for pane.spawn argv (never repo scope; env/cwd overrides must be empty or allowlisted; match argv arrays, never shell strings); pane.write limited to panes the calling session spawned; (5) tighten the safe tiers first — narrow the ~/.claude extra read root, confine image/draw/icon paths, sanitise clipboard set. Needs a D-record: touches D-6 parity and D-71 (no per-client socket auth).', 'backlog', 'high', NULL, NULL, 'D-115', '2026-09-23 08:27:19.441', '2026-09-23 12:00:31.782', NULL, 'ff397e74d59e1be5d2c8f10be2c514c1', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR6TQGT92QMWYBWVJJKVPG', 'task', '06GCTR272F195FXFG583PV7FP8', 'Narrow the committed .claude/settings.json allow rules', 'Scan finding M13. The committed project settings apply to anyone who clones this public repo and runs Claude Code in it, and several allow rules are broader than the workflow needs (interpreter-level dart/flutter, every make target, git config, git push guarded only against a few force spellings). Narrow to the specific subcommands the workflow uses, drop git config, add denies for the push/checkout/branch-delete forms that slip past today. Coordinate with the generated clide allow rules from T-602.', 'backlog', 'medium', NULL, NULL, 'D-115', '2026-09-23 08:27:51.868', '2026-09-23 12:00:31.789', NULL, '306d8da00407d0131e0d3b3cbafbd086', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR6TQGT92QMWYBWVJJKVPG', 'task', '06GCTR272F195FXFG583PV7FP8', 'Narrow the committed .claude/settings.json allow rules', 'Scan finding M13. The committed project settings apply to anyone who clones this public repo and runs Claude Code in it, and several allow rules are broader than the workflow needs (interpreter-level dart/flutter, every make target, git config, git push guarded only against a few force spellings). Narrow to the specific subcommands the workflow uses, drop git config, add denies for the push/checkout/branch-delete forms that slip past today. Coordinate with the generated clide allow rules from T-602.

Folded into T-602 per D-115: the committed .claude/settings.json allow list is generated from the observe/display tiers there. Close together with T-602.', 'backlog', 'medium', NULL, NULL, 'D-115', '2026-09-23 08:27:51.868', '2026-09-23 12:00:32.796', NULL, '34a1ac6b42ef956a56d5a8de964adfb9', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCTR2W244VDCCYYYMZE823MR', 'story', '06GCTR272F195FXFG583PV7FP8', 'Risk tiers for clide verbs: generated agent allow rules + in-app confirm for escalating verbs', 'Scan finding H1 (+ the report''s allowlist proposal). Hosted Claude sessions are pre-approved for every clide verb, including verbs that spawn processes or write to panes. Plan: (1) a required risk tier on every registry command — observe / display / workspace-write / escalate — enforced by a registry test so no verb ships unclassified; (2) generate the agent''s Claude allow rules from the observe+display tiers (a capabilities flag), replacing the blanket rule in agent_bootstrap and the committed .claude/settings.json; (3) the dispatcher asks the user in-app before any escalate verb arriving over the socket, showing full argv/env/target; (4) an app-scope allowlist for pane.spawn argv (never repo scope; env/cwd overrides must be empty or allowlisted; match argv arrays, never shell strings); pane.write limited to panes the calling session spawned; (5) tighten the safe tiers first — narrow the ~/.claude extra read root, confine image/draw/icon paths, sanitise clipboard set. Needs a D-record: touches D-6 parity and D-71 (no per-client socket auth).

Decided in D-115 (2026-09-23): workspace-write gets Claude''s normal prompt; in-app confirm for agent-origin escalate calls (Linux process ancestry, else all socket calls), allow once or for this session; escalate verbs hidden from MCP; app-scope argv spawn allowlist; agents type freely into their own panes, others confirm; files write refuses .git/ and .claude/; ~/.claude read root narrowed to skills/agents/commands. Clipboard (T-613) and image/draw/icon paths (T-617) stay separate.', 'backlog', 'high', NULL, NULL, 'D-115', '2026-09-23 08:27:19.441', '2026-09-23 12:00:34.503', NULL, '9aa09d6f5713d0b6815cc8bc06ac80c2', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
