INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCWJKJZAT6YR5EPX6A9ZP9V4', 'task', '06FB0TNQM5TWC00GW0P3X02HZW', 'Status bar: context size turns warning at 75% and error at 95%', 'The Claude context label in the status bar (claude_status.dart, _contextLabel: tokens / window) is always the default text color. Color that segment by fill: statusWarning at 75% of the context window or more, statusError at 95% or more, normal below. Theme tokens only, no hardcoded colors. Only possible when the window is known (status.contextWindow); with a bare token count there is no percentage, so leave it uncolored. Keep the thresholds as named constants. The same label also renders in the meta sidebar (claude_meta_sidebar.dart, roster_row.dart), so apply it there too for consistency. Tests: below 75, exactly 75, between, exactly 95, above, unknown window.', 'backlog', 'medium', NULL, NULL, NULL, '2026-09-23 12:43:00.730', '2026-09-23 12:43:00.730', NULL, '903ac24d749b79a3b6a500436406ffd2', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
