INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCXBABKEB9RR65ZVQQJVJG0G', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'pql tests run against an inherited PQL_VAULT and write into it', NULL, 'backlog', 'high', NULL, NULL, NULL, '2026-09-23 14:30:58.715', '2026-09-23 14:30:58.715', NULL, '121a1f1e046cb2faef410c18336bc633', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCXBABKEB9RR65ZVQQJVJG0G', 'bug', '06GCVS5HZ69QKQB198ZR1Y3YB4', 'pql tests run against an inherited PQL_VAULT and write into it', 'When `PQL_VAULT` is set in the environment, the pql tests run `pql` against that vault instead of their fixture. This affects `test/pql/client_test.dart` and `test/daemon/pql_commands_test.dart`.

- 18 tests fail: 14 in the client test and 4 in the daemon commands test.
- **The ticket tests also write into the named vault.** They create "Fixture epic" / "Fixture child" tickets there, and change the status of whatever ticket carries the fixture''s id.

With the variable unset, both files pass (57 tests). A developer who exports `PQL_VAULT` for their own work therefore gets a red suite and a modified vault from `make test`.

**Fix:**
- Scrub `PQL_VAULT`, `PQL_DB` and `PQL_CONFIG` from the environment of every `pql` process the tests spawn.
- Add a hermetic test that fails if any `PQL_*` variable reaches one.

**Done when:**
- `PQL_VAULT=/some/other/vault make test` passes.
- It leaves that vault untouched.', 'backlog', 'high', NULL, NULL, NULL, '2026-09-23 14:30:58.715', '2026-09-23 14:30:58.875', NULL, 'f9462bcb2d3d09d2abefdc6f983be31c', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCXBACVJ4TMMNGH31VV6A8A0', 'bug', '06FB0TNQM6T6580D8ABDVTMNZW', 'Vendored libtree-sitter.so needs glibc 2.34; fails to load on older hosts', NULL, 'backlog', 'medium', NULL, NULL, NULL, '2026-09-23 14:30:59.036', '2026-09-23 14:30:59.036', NULL, '26dd157f7f0f7b7e1db719af0b63d86a', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCXBACVJ4TMMNGH31VV6A8A0', 'bug', '06FB0TNQM6T6580D8ABDVTMNZW', 'Vendored libtree-sitter.so needs glibc 2.34; fails to load on older hosts', 'The vendored `native/linux-x64/libtree-sitter.so` is built on a recent distribution and needs glibc 2.34 or later: 11 of its symbols are versioned `GLIBC_2.34`. On a glibc 2.31 host (Ubuntu 20.04-based distributions), `DynamicLibrary.open` fails with ``version `GLIBC_2.34'' not found``. Two consequences on such hosts:
- the native tree-sitter smoke test fails;
- the desktop app cannot load tree-sitter.

**Options:**
- Rebuild against an older glibc baseline, for example in a manylinux-style build container. This follows D-63.
- Or declare a minimum glibc, and state it in `BUILD.md` and the install docs.

The web UI image has the same floor (Q-53 c).

**Done when:**
- The supported glibc floor is decided and written down.
- The vendored library loads on it.
- CI builds or tests on that floor.', 'backlog', 'medium', NULL, NULL, NULL, '2026-09-23 14:30:59.036', '2026-09-23 14:30:59.195', NULL, '430e800d23e1ac29e808ee65a7ab4ed7', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G64PCW3KDVCV1X83543FA5JC', 'bug', '06GCXAZ7713854V2WXTFREB68C', 'Web target: fence has runtime holes the wasm compile gate can''t see', 'Spike write-up: `docs/spikes/web-target-2026-09-02.md`. Built `flutter build web --wasm` at v2.12.0, served it, loaded it in Chrome, read the console and access log.

**The build succeeds and the app boots surprisingly far** — WASM, all fonts, all 12 themes, i18n catalogs, extension registration, keymap — then throws `Unsupported operation: _Namespace` and never paints. That''s `dart:io`''s filesystem layer, which has no web implementation.

## The finding that matters

D-100 fences `dart:ffi` and adds a `flutter build web --wasm` CI step "so the fence can''t silently rot". **That gate proves the tree compiles; it cannot prove the tree boots** — and those two came apart. This is a D-108 case in the wild: a negative check ("it didn''t fail to compile") standing in for a positive one, so compiling got mistaken for working.

Two holes, found only by running it:

1. **`main.dart:114`** — `resolveWorkspaceRoot(Directory.current)` sits six lines ABOVE the `if (!kIsWeb)` guard protecting everything after it. Constructing a `Directory` is inert on web; resolving one is not. **Fixed in the spike commit** (one line); took the boot from "themes loaded" to "extensions registered".
2. **A second `_Namespace`** during extension activation — NOT fixed. Twelve files on the activation path call existsSync/createSync/listSync/readAsStringSync: terminal_pane, conversation_view, path_preset_control, agent_bootstrap, account_registry, claude_pane, claude_config, cli_install, watchdog, toolchain_paths, file_log_sink, tree_sitter_ffi.

## Scope of THIS ticket

Keep it to making the fence honest — not porting the app:

- Plug hole 2 (and any it reveals) so the app paints.
- **Make the CI web job boot the bundle and assert first paint**, not merely compile it. Without that the next hole lands the same silent way. The harness exists (`tools/ui/`, D-26) and is already ticketed as **T-443**; it is currently dead — the Playwright browser isn''t even installed locally, which is how this went unnoticed.
- Quieten the i18n fallback probe: it emits ~20 404s + red engine errors per clean boot (probing `assets/i18n/en/*` before `en_us`), burying real errors exactly when you need to read them.

## Explicitly NOT this ticket

There is no IPC client on web at all — `main.dart:561` passes `daemonClientFactory: kIsWeb ? null : …`. Even with every hole plugged the UI would paint and do nothing, because the transport is a Unix socket a browser can''t open. That''s an absent layer, not a bug, and it''s a product decision (D-100 says web is a UI/e2e surface, not a functional replacement).

**If that decision is ever revisited, sequence it behind T-399.** "RemoteExecutionContext seam — subsystems stop calling Process.run/File directly" is verbatim the refactor a web backend needs; the web port and the SSH-remote epic (T-336) are the same work with a different pipe on the end. Doing them independently builds the same seam twice.

Note also that with such a seam the terminal is NOT a blocker: xterm.dart renders fine in a browser, and only the *spawn* is native. D-100''s "no PTY/terminal on web" is true of a standalone build, not of a front end to a host that owns the pty.', 'backlog', 'medium', NULL, NULL, NULL, '2026-09-02 13:40:34.972', '2026-09-23 14:31:25.350', NULL, '7a552cf76a269c57a7482df358301c94', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06FCQZ47MAN835B215GSSMRV8W', 'task', '06GCXAZ7713854V2WXTFREB68C', 'Wire the web-WASM Playwright e2e back into CI (make test-e2e / ui-smoke)', 'Follow-up from T-438 (the `dart:ffi` web fence, D-100): with `flutter build web --wasm` compiling again and a compile gate in CI, restore the *full* web-WASM Playwright e2e — the remaining slice of T-438''s acceptance.

**What''s already done (T-438).** The web build compiles; `.github/workflows/test.yml` has a `web-wasm` job that runs `flutter build web --wasm` (the anti-rot compile gate); `make ui-dev` (build + serve) works.

**What this ticket adds.** The actual browser e2e, which needs runner provisioning the compile gate doesn''t:
- `make test-e2e` / `make ui-smoke` run green locally and in CI (build → serve `localhost:4280` → Playwright smoke → teardown).
- A GitHub Actions job: `setup-node`, `npm install` + `npx playwright install --with-deps` in `tools/ui/`, then `make test-e2e`. Add it to `.github/workflows/test.yml` (replacing the compile-only `web-wasm` job, or as a second job that `needs` it).
- Confirm the Playwright driver (D-26) still matches the current web entrypoint after the fence (degraded web build: no terminal/native-git/highlighting — the smoke should assert what *does* render, e.g. the shell boots and a pane mounts).

**Acceptance.** `make test-e2e` and `make ui-smoke` pass locally; a CI job runs the Playwright smoke against the wasm build on every push/PR; D-26/D-32 reflect the restored e2e job.

**Refs:** T-438 (compile fence + gate), D-100 / Q-50 (fence decision), D-26 (Playwright driver), D-32 (CI; the withheld e2e job).', 'backlog', 'medium', NULL, NULL, 'D-26', '2026-06-15 15:53:05', '2026-09-23 14:31:25.394', NULL, 'c457142bf682a6f0811e31cb5732636d', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCXB9EJTH1WYNJ8DJE2T72R4', 'story', '06GCXAZ5MQRY0C7RHVJFF3ER3G', 'Record the web UI decisions and amend the guardrails', 'Recorded D-116 (web UI mode), D-117 (front door) and R-13 (no API wrapper); opened Q-52 and Q-53; amended D-100, D-94, D-56 and the CLAUDE.md guardrails.', 'done', 'high', NULL, NULL, 'D-116', '2026-09-23 14:30:51.286', '2026-09-23 14:31:30.752', NULL, 'bf48b03d0e8bc4d21a5bd355acedb08d', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
