INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GD4N6P6EZ9FFV5K2GRZMEM7C', 'story', '06GCXAZ8KHR81WFY1WN4QQWSRC', 'Broker store on Postgres', 'The broker''s store (D-121) on Postgres, beside the SQLite default: the client, the adapter, and the store''s test suite run against Postgres in CI.', 'backlog', 'medium', NULL, NULL, 'D-121', '2026-09-24 07:32:50.355', '2026-09-24 07:32:50.355', NULL, 'aa6efac6708f195bdbabceb26ed70313', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GD4N6P6EZ9FFV5K2GRZMEM7C', 'story', '06GCXAZ8KHR81WFY1WN4QQWSRC', 'Broker store on Postgres', 'The broker''s store (D-121) on Postgres, beside the SQLite default: the client, the adapter, and the store''s test suite run against Postgres in CI.

**Goal.** The broker''s store runs on Postgres as well as on its SQLite default, with the same schema and statements (D-121).

**Scope:**
- **The client, decided first under D-31 and D-61.** Either clide owns the protocol subset the store needs, or it takes `package:postgres`. Owning it means: startup, SCRAM-SHA-256 authentication, the extended query protocol with text-format parameters and results, errors, and TLS when the URL asks for it. Taking the package means its maintainership and its transitive dependencies get the D-61 checklist.
- **The adapter** behind the store interface T-664 defines. It is chosen by a `postgres://` store URL, with the password taken from `CLIDE_BROKER_STORE_PASSWORD` or its `_FILE` variant and refused in the URL.
- **Migrations** take an advisory lock, so two brokers starting together apply them once.
- **Tests.** The store''s suite runs against Postgres whenever a test server is configured. A CI job runs it against a Postgres service container. Without a server the Postgres cases skip, and the adapter stays thin enough that the coverage gate does not depend on them.
- **Docs:** the store URL and the password variables in the broker''s configuration reference.

**Done when:** the full store suite passes against Postgres in CI, and a broker pointed at Postgres signs in, keeps its sessions across a restart, and shows its settings with `clide_broker settings list`.', 'backlog', 'medium', NULL, NULL, 'D-121', '2026-09-24 07:32:50.355', '2026-09-24 07:33:05.257', NULL, '0fff202b2b34e795447945cd1fc50c47', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
